import { For } from '@pyreon/core'
import { Button, Field, Scroll, Stack, Text } from '@pyreon/primitives'
import { signal } from '@pyreon/reactivity'

type Todo = { id: number; text: string }

export function Todos() {
  const draft = signal('')
  const todos = signal<Todo[]>([])

  const add = () => {
    if (draft() === '') return
    todos.set([...todos(), { id: todos().length + 1, text: draft() }])
    draft.set('')
  }

  return (
    <Stack gap="sm" padding={4}>
      <Field value={draft()} onChangeText={(t) => draft.set(t)} onSubmit={add} placeholder="New todo" />
      <Button onPress={add}>Add</Button>
      <Scroll>
        <For each={todos} by={(t) => t.id}>
          {(t) => <Text>{t.text}</Text>}
        </For>
      </Scroll>
    </Stack>
  )
}
